const {esc,api,toast,closeModal}=window;
let c07ImportState=null;
const c07old=window.operationsLearningTab;
window.operationsLearningTab=async(el,p)=>{await c07old(el,p);el.insertAdjacentHTML('beforeend',`<section class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>ATS / 渠道 CSV 导入</h3><span class="subtle">两阶段导入：先 Preview/校验并生成 SHA-256，再按同一摘要 Commit。导入数据默认仍是 advisory，不进入候选人评分。</span></div><button class="btn small primary" onclick="c07OpenImport()">导入 CSV</button></div><div class="panel-body"><div class="status good">Host-ready</div><span class="subtle" style="margin-left:8px">当前主线已恢复 0.8.x WPF Host runtime ABI；Windows Native 由精确 v0.8.8 carrier 继承，不伪造本机未验证的 Host 二进制。</span></div></section>`)};
window.c07OpenImport=()=>{modalWide('导入渠道漏斗 CSV',`<div class="form-grid"><div class="field full"><label>CSV 文件</label><input id="c07-file" class="input" type="file" accept=".csv,text/csv"></div><div class="field full"><label><input id="c07-confirmed" type="checkbox"> 我已人工核对本次导入的全部漏斗数据</label></div><div id="c07-preview" class="field full"><div class="empty">选择文件后先执行 Preview；校验通过后才允许 Commit。</div></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn" onclick="c07PreviewImport()">Preview</button><button id="c07-commit-btn" class="btn primary" disabled onclick="c07CommitImport()">Commit</button>`)};
window.c07PreviewImport=async()=>{const f=document.querySelector('#c07-file')?.files?.[0];if(!f){toast('请选择 CSV 文件',true);return}try{const content=await f.text();const r=await api(`/api/v1/projects/${window.__c05ProjectId}/sourcing-observations/import-preview`,{method:'POST',body:JSON.stringify({content})});c07ImportState={file:f,content,preview:r};const box=document.querySelector('#c07-preview');box.innerHTML=`<div class="status ${r.can_commit?'good':'danger'}">${r.can_commit?'可提交':'存在错误，禁止提交'}</div><div class="subtle" style="margin-top:6px">SHA-256: ${esc(r.digest)} · ${r.row_count} 行有效 · ${r.error_count} 行错误 · delimiter=${esc(r.detected_delimiter)}</div>${r.errors?.length?`<div class="quick-list" style="margin-top:8px">${r.errors.map(x=>`<div class="quick-item"><div><strong>第 ${x.row_number} 行</strong><div class="quick-note">${esc(x.error)}</div></div></div>`).join('')}</div>`:`<div class="table-wrap" style="margin-top:8px"><table class="table"><thead><tr><th>渠道</th><th>期间</th><th>漏斗</th><th>成本</th><th>确认</th></tr></thead><tbody>${r.rows.slice(0,20).map(x=>`<tr><td>${esc(x.channel)}</td><td>${esc(x.period||'—')}</td><td>${x.sourced}→${x.contacted}→${x.screened}→${x.interviewed}→${x.offered}→${x.hired}</td><td>¥${x.spend_cny}</td><td>${x.human_confirmed?'CSV 已标记':'advisory'}</td></tr>`).join('')}</tbody></table></div>`}`;document.querySelector('#c07-commit-btn').disabled=!r.can_commit}catch(e){toast(e.message,true)}};
window.c07CommitImport=async()=>{if(!c07ImportState?.preview?.can_commit){toast('请先完成有效 Preview',true);return}try{const r=await api(`/api/v1/projects/${window.__c05ProjectId}/sourcing-observations/import-commit`,{method:'POST',body:JSON.stringify({content:c07ImportState.content,expected_digest:c07ImportState.preview.digest,filename:c07ImportState.file.name,human_confirmed:document.querySelector('#c07-confirmed').checked,actor:'human'})});closeModal();toast(`已导入 ${r.imported_count} 条渠道观测`);c05Reload()}catch(e){toast(e.message,true)}};
